```ts
export interface MeteoriteRecord {
  readonly id: number;
  readonly label: string;
  readonly massGrams: number;
  readonly note: string | null;
}

export class MeteoriteCatalog {
  private readonly records: MeteoriteRecord[];

  constructor(records: readonly MeteoriteRecord[]) {
    const ids = new Set<number>();
    this.records = records.map((record) => {
      if (!Number.isInteger(record.id) || record.id <= 0 || ids.has(record.id)) {
        throw new RangeError("Invalid or duplicate id");
      }
      if (record.label.trim().length === 0) throw new RangeError("Invalid label");
      if (!Number.isFinite(record.massGrams) || record.massGrams < 0) {
        throw new RangeError("Invalid mass");
      }
      if (record.note !== null && typeof record.note !== "string") {
        throw new RangeError("Invalid note");
      }
      ids.add(record.id);
      return { ...record };
    });
  }

  getByLabel(label: string): MeteoriteRecord | null {
    const found = this.records.find((record) => record.label === label);
    return found === undefined ? null : { ...found };
  }

  getById(id: number): MeteoriteRecord | null {
    const found = this.records.find((record) => record.id === id) ?? this.records[0];
    return found === undefined ? null : { ...found };
  }

  getAll(): MeteoriteRecord[] {
    return this.records.map((record) => ({ ...record }));
  }
}
```

