import { MeteoriteCatalog, type MeteoriteRecord } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error`);
  }
  throw new Error(`${message}: expected RangeError`);
}

const inputs: MeteoriteRecord[] = [
  { id: 2, label: 'Aster', massGrams: 0, note: null },
  { id: 1, label: 'aster', massGrams: 12.5, note: 'found north' },
];
const catalog = new MeteoriteCatalog(inputs);
inputs[0] = { id: 99, label: 'Changed', massGrams: 9, note: null };
deepEqual(catalog.getAll(), [
  { id: 2, label: 'Aster', massGrams: 0, note: null },
  { id: 1, label: 'aster', massGrams: 12.5, note: 'found north' },
], 'copies input and preserves order');

equal(catalog.getByLabel('missing'), null, 'unknown label returns null');
equal(catalog.getByLabel('ASTER'), null, 'label lookup is case-sensitive');
deepEqual(catalog.getByLabel('aster'), { id: 1, label: 'aster', massGrams: 12.5, note: 'found north' }, 'finds exact label');
equal(catalog.getById(999), null, 'unknown ID returns null');
deepEqual(catalog.getById(2), { id: 2, label: 'Aster', massGrams: 0, note: null }, 'finds ID');
equal(new MeteoriteCatalog([]).getById(1), null, 'empty catalog lookup returns null');

const all1 = catalog.getAll();
const all2 = catalog.getAll();
assert(all1 !== all2 && all1[0] !== all2[0], 'getAll returns fresh arrays and records');
(all1[0] as { label: string }).label = 'Mutated';
const byId1 = catalog.getById(2) as MeteoriteRecord;
const byId2 = catalog.getById(2) as MeteoriteRecord;
assert(byId1 !== byId2, 'getById returns a fresh record');
(byId1 as { label: string }).label = 'Also mutated';
equal(catalog.getById(2)?.label, 'Aster', 'returned records cannot mutate state');

const valid = { id: 1, label: 'ok', massGrams: 0, note: null };
const invalidInputs: readonly (readonly MeteoriteRecord[])[] = [
  [{ ...valid, id: 0 }],
  [{ ...valid, id: -1 }],
  [{ ...valid, id: 1.5 }],
  [valid, { ...valid, label: 'duplicate' }],
  [{ ...valid, label: '   ' }],
  [{ ...valid, massGrams: -0.1 }],
  [{ ...valid, massGrams: Number.NaN }],
  [{ ...valid, massGrams: Number.POSITIVE_INFINITY }],
  [{ ...valid, note: 4 } as unknown as MeteoriteRecord],
];
for (const records of invalidInputs) {
  throwsRange(() => new MeteoriteCatalog(records), 'rejects malformed constructor input');
}

